"""Explain report settings, prefix filtering, bounds and string cleanup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1829': ('설정표에 적는 이름과 프로그램 안에서 값을 보관하는 상자 이름은 다를 수 있어요. 둘을 연결하는 코드를 읽어 봐요.', '외부 설정 이름과 내부 변수, 보고 뒤 중단 조건을 구별합니다.', 'kmsan.와 panic을 이어 kmsan.panic을 쓰고, 그 옆에 내부 변수 panic_on_kmsan을 연결하세요.', ['KMSAN은 준비되지 않은 메모리 값을 사용하는 실수를 찾는 도구예요. panic_on_kmsan은 오류를 보고한 뒤 커널 panic을 일으킬지 정하는 정수 변수예요. 커널은 운영체제의 핵심 부분이고 panic은 정상 실행을 계속할 수 없다고 처리하는 경로예요.', '코드에서는 MODULE_PARAM_PREFIX를 kmsan.으로 정해요. prefix는 이름 앞에 붙이는 부분이라는 뜻이에요. 그다음 module_param_named에서 외부 이름 panic을 내부 변수 panic_on_kmsan과 연결해요.', '앞부분 kmsan.과 이름 panic을 붙이면 kmsan.panic이 돼요. 내부 변수 이름을 그대로 이어 panic_on_kmsan.enable이라고 만드는 것은 아니에요. 이 선언의 int는 설정값을 정수로 다룬다는 뜻이에요.', '선언의 마지막 0은 설정값 자체가 아니라 sysfs에 나타내는 권한 인자예요. sysfs는 커널 정보를 파일처럼 보여 주는 창구예요. 이 인자가 0이면 해당 매개변수를 sysfs에 나타내지 않아요. 그래서 쓰기 가능한 설정 파일이 반드시 있다고 생각하면 안 돼요.', 'kmsan_report가 보고를 끝내는 경로에서는 먼저 보고 잠금을 풀고 panic_on_kmsan을 확인해요. 값이 0이 아니면 panic을 호출해요. 0이면 그 호출을 건너뛰고 접근 상태 복구와 보고 억제 해제 코드로 이어져요.', 'panic은 조용히 기록을 지우는 기능이 아니에요. 실제 panic 경로는 일반 함수처럼 돌아와 다음 줄을 실행하지 않아요. 종이에 0과 1의 두 길을 그리는 실습으로 조건을 이해하세요. 설정이 1이어도 보고 함수 입구에서 이미 돌아갔다면 이 끝부분에 도달하지 않아요.'], [('앞부분 kmsan.과 외부 이름 panic을 합친 설정 이름은 무엇인가요?', ['panic_on_kmsan.enable이에요', 'kmsan.panic이에요'], '정답은 두 번째예요. kmsan. 뒤에 panic을 붙여요. panic_on_kmsan은 값을 담는 내부 변수 이름이므로 외부 설정 이름과 구별하세요.'), ('보고 끝의 조건에 도달했고 panic_on_kmsan이 0이 아니라면 무엇을 호출하나요?', ['정상 실행을 계속하지 않는 kernel panic 경로예요', '기록만 조용히 지우고 아무 일 없이 돌아가는 경로예요'], '정답은 첫 번째예요. if 조건 바로 뒤에 panic 호출이 있어요. 호출만 기록하고 돌아오는 학습 모형이 있더라도 실제 panic도 그렇게 돌아온다는 뜻은 아니에요.')]), 'os1830': ('줄 맨 앞에 안내 직원 두 명이 있고 그 뒤에 손님이 있다면, 안내 직원 두 명만 지나 첫 손님부터 볼 수 있어요. 이 함수도 앞부분만 건너뛰어요.', '이름의 시작 부분을 검사해 앞쪽 내부 호출 기록만 건너뛰는 원리를 이해합니다.', 'kmsan_a, __msan_b, work, kmsan_c 순서로 적고 처음 두 이름만 건너뛴 뒤 멈추세요.', ['함수가 다른 함수를 부르면 호출 경로가 생겨요. stack trace는 그 경로를 보여 주는 기록이고 frame은 그 안의 한 항목이에요. 오류 보고에서 검사 도구 자신의 호출만 먼저 길게 보이면 실제 문제를 찾기 어려울 수 있어요.', 'get_stack_skipnr는 맨 앞에서 몇 항목을 건너뛸지 계산해요. skip은 건너뛴 개수예요. 각 주소를 scnprintf로 함수 이름 문자열에 표현하고, 그 문자열의 시작이 __msan_ 또는 kmsan_인지 확인해요.', 'strnstr는 정해진 길이 안에서 글자 조각을 찾아요. 여기서는 찾았다는 사실만 보는 것이 아니라 결과가 buf와 같은지도 비교해요. buf는 문자열의 시작 주소라서, 이 비교는 맨 처음부터 그 이름으로 시작하는지를 묻는 거예요.', '이름이 kmsan_read라면 kmsan_이 처음에 있으므로 건너뛰어요. prefix_kmsan_read라면 중간에 있으므로 이 조건으로 건너뛰지 않아요. 이름 안에 포함되는 것과 이름이 그것으로 시작하는 것은 달라요.', '내부 이름이면 continue로 다음 항목을 확인하고, 처음 일반 이름을 만나면 break로 반복을 끝내요. kmsan_a, __msan_b, work, kmsan_c라면 앞의 둘만 건너뛰어 결과는 2예요. work 뒤의 kmsan_c까지 찾아 삭제하지 않아요.', '이 함수는 원래 배열의 항목을 지우거나 순서를 바꾸지 않아요. 앞에서 생략할 개수만 돌려줘요. 뒤의 출력 코드가 그 개수를 이용해 어느 위치부터 보여 줄지 정해요.'], [('기록이 내부 이름·내부 이름·일반 이름 순서라면 건너뛸 개수는 얼마인가요?', ['세 항목을 모두 지우므로 3이에요', '첫 일반 이름 앞의 두 항목이므로 2예요'], '정답은 두 번째예요. 앞의 둘은 continue로 지나가고 일반 이름에서 break로 멈춰요. 원래 항목을 삭제하는 함수도 아니에요.'), ('prefix_kmsan_internal도 kmsan_으로 시작한다고 보나요?', ['아니요. kmsan_은 중간에 있으므로 시작 조건에 맞지 않아요', '네. 어디든 kmsan_이 들어 있으면 시작 조건에 맞아요'], '정답은 첫 번째예요. 검색 결과가 문자열 시작 주소와 같은지 비교해요. 이 이름은 prefix_로 시작하므로 중간에 kmsan_이 보여도 같은 조건이 아니에요.')]), 'os1831': ('상자가 두 개면 번호는 0번과 1번이에요. 두 개를 모두 지나갔다는 숫자 2가 남아 있다고 해서 2번 상자도 있는 것은 아니에요.', '건너뛴 개수와 읽을 수 있는 항목 번호를 구별합니다.', '0번과 1번 카드 두 장을 그리세요. 둘을 지나면 남은 장수는 0이며 새 2번 카드가 생기지 않는다고 적으세요.', ['get_stack_skipnr는 앞에 이어진 검사 도구 내부 기록의 개수를 돌려줘요. 반환값은 건너뛴 개수이지 언제나 읽을 수 있는 항목 번호라는 보장은 아니에요. C 배열은 첫 항목을 0번부터 세어요.', '기록 두 개가 모두 내부 이름이면 0번과 1번을 건너뛰어요. 반복이 끝나 skip은 2가 되고 그대로 반환돼요. 마지막 항목 번호인 1을 돌려주는 것이 아니에요.', '입력 기록이 하나도 없으면 처음 skip 값 0에서 반복에 들어가지 않고 0을 반환해요. 결과가 0이라는 사실만으로 0번 기록이 존재한다고 판단할 수도 없어요. 입력 개수와 함께 봐야 해요.', '두 기록에서 둘을 건너뛰면 남은 개수는 2 - 2 = 0이에요. entries + skip과 길이 0을 전달해 빈 범위를 나타내는 것과 entries[skip]으로 값을 하나 직접 읽는 것은 달라요. 두 칸짜리 배열이라면 끝 바로 다음 위치를 표현할 수 있어도 그곳의 값을 읽으면 안 돼요.', '실제 kmsan_report에는 stack_entries[skipnr]를 첫 문제 위치로 읽는 코드와 남은 길이로 경로를 출력하는 코드가 함께 있어요. 저장 배열의 전체 용량이 수집한 기록 수보다 크더라도, 수집한 기록 바로 다음 칸을 유효한 기록이라고 보장할 수는 없어요.', '따라서 첫 문제 위치를 직접 읽는 호출자는 건너뛴 뒤 관심 있는 기록이 남는다는 전제를 확인해야 해요. 이 helper 자체가 마지막에 안전한 번호로 고쳐 주지는 않아요. 종이 예시는 반환값의 경계를 설명하며 실제 커널에서 해당 상황이 발생했다는 실험 결과는 아니에요.'], [('두 기록이 모두 내부 이름이면 helper가 반환하는 수는 무엇인가요?', ['마지막 기록 번호인 1이에요', '건너뛴 기록 수인 2예요'], '정답은 두 번째예요. 두 기록을 모두 지났으므로 2예요. 이 값은 개수이므로 유효한 항목 번호라고 그대로 쓰면 안 돼요.'), ('entries[skip]으로 한 값을 읽는 것과 남은 길이 0을 전달하는 것은 같은가요?', ['아니요. 한 값을 직접 읽는 일과 빈 범위를 표현하는 일은 달라요', '네. 둘 다 언제나 같은 칸을 읽어요'], '정답은 첫 번째예요. 빈 범위에는 읽을 항목이 없어요. 반면 직접 읽기는 그 위치에 유효한 항목이 있어야 해요. 주소 계산, 수집한 개수, 배열의 실제 용량을 함께 구별하세요.')]), 'os1832': ('이름표에서 장식 기호를 빼고 이름만 옮겨 적어 봐요. -는 건너뛰고 @를 만나면 그 뒤는 옮기지 않는 규칙이에요.', '문자열의 건너뛰기와 반복 종료를 한 글자씩 따라갑니다.', '----local-name@function에서 -를 모두 지우고 첫 @부터 뒤를 가려 localname을 남기세요.', ['pretty_descr는 컴파일러가 만든 지역 변수 설명을 짧게 가공해요. 컴파일러는 소스 코드를 실행할 수 있는 형태로 바꾸는 도구예요. 원문의 설명 예는 ----local_name@function_name이에요. 보고에서는 변수 이름을 읽기 쉽게 보여 주려 해요.', '문자열은 글자가 차례로 놓인 데이터예요. i는 지금 읽는 글자의 위치이고 pos는 결과를 쓸 위치예요. 읽은 글자를 모두 복사하지 않으므로 두 위치가 항상 같이 늘어나는 것은 아니에요.', '현재 글자가 @이면 break로 반복을 끝내요. @도 복사하지 않고 그 뒤의 함수 이름도 옮기지 않아요. 현재 글자가 -이면 continue로 이번 글자만 건너뛰고 다음 글자를 살펴요. 반복 전체를 끝내는 break와 달라요.', '그 밖의 글자는 결과 배열에 써요. 그래서 ----local-name@function은 앞의 네 -를 지나 local을 쓰고, 중간 -도 지나 name을 쓴 뒤 @에서 멈춰요. 결과는 localname이에요. 처음에 있는 -만 지우는 규칙이 아니에요.', '결과는 report_local_descr라는 공용 배열에 담고 마지막에 문자열 끝을 뜻하는 0을 넣어요. 128칸 중 끝 표시를 남겨야 하므로 내용은 최대 127글자예요. 여기서 글자 수 설명은 예시처럼 한 바이트 문자로 된 이름을 기준으로 해요.', '예를 들어 a-b@c-d는 ab가 되고, @abc는 처음부터 멈춰 빈 문자열이 돼요. ab-c처럼 @가 없으면 읽을 글자 끝까지 진행해 abc가 돼요. 입력과 결과를 나란히 쓰면 건너뛰기와 종료의 차이를 확인할 수 있어요.'], [('----local-name@function을 가공하면 무엇이 남나요?', ['local-name@function이 그대로 남아요', 'localname이 남아요'], '정답은 두 번째예요. 앞과 중간의 -를 모두 건너뛰고 @에서 멈춰요. @와 function은 결과에 넣지 않아요.'), ('첫 @를 만난 뒤에도 함수 이름을 계속 복사하나요?', ['아니요. break로 반복을 끝내요', '네. 원래 설명 전체를 반드시 복사해요'], '정답은 첫 번째예요. @는 종료 조건이에요. -에서 실행하는 continue는 다음 글자로 가지만, @에서 실행하는 break는 반복 밖으로 나가요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_453.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
